/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        scwin.form = (document.prelistMainForm || { elements: [] });
        $c.util.getComponent('slc_ventDesignRsnCd').setDisabled(true);
        $c.util.getComponent('slc_ventDesignRsnCd').setSelectedIndex(0);
        $c.util.getComponent('rd_prelmInvstgComTpCd1').setItemDisabled(0, !!(true));
        $c.util.getComponent('rd_prelmInvstgComTpCd1').setItemDisabled(1, !!(true));
        $c.util.getComponent('rd_prelmInvstgComTpCd1').setValue('5');
        if ($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd") === "") {
            $c.util.getComponent("dma_RegisterReq").set("billLstSaveStatCd", "0");
        }
        if ($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd") === "") {
            return;
        }
        scwin.onloadDataSet();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05041.onload" });
    }
};

/**
 * @method
 * @name onloadDataSet
 * @description onload Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.onloadDataSet = function () {
    try {
        const corpRegNo = $c.util.getComponent("dma_RegisterReq").get("corpRegNo");
        const bzRegNo = $c.util.getComponent("dma_RegisterReq").get("bzRegNo");
        const fscRegDd = $c.util.getComponent('cal_fscRegDd').getValue();
        const billSubmitDd = $c.util.getComponent('cal_billSubmitDd').getValue();
        const clmPlandocSubmitDd = $c.util.getComponent('cal_clmPlandocSubmitDd').getValue();
        const zipcd = $c.util.getComponent("dma_RegisterReq").get("zipcd");
        const foundDd = $c.util.getComponent('cal_foundDd').getValue();
        if (corpRegNo.length !== 0) {
            $c.util.getComponent('ipt_corpRegNo1').setValue(corpRegNo.substring(0, 6));
            $c.util.getComponent('ipt_corpRegNo2').setValue(corpRegNo.substring(6));
        }
        if (bzRegNo.length !== 0) {
            $c.util.getComponent('ipt_bzRegNo1').setValue(bzRegNo.substring(0, 3));
            $c.util.getComponent('ipt_bzRegNo2').setValue(bzRegNo.substring(3, 5));
            $c.util.getComponent('ipt_bzRegNo3').setValue(bzRegNo.substring(5));
        }
        if (zipcd.length !== 0) {
            $c.util.getComponent('ipt_zipcd1').setValue(zipcd.substring(0, 3));
            $c.util.getComponent('ipt_zipcd2').setValue(zipcd.substring(3));
        }
        scwin.checkFscRegYn($c.util.getComponent('ipt_fscRegYn').getValue());
        if ($c.util.getComponent("dma_RegisterReq").get("prelmInvstgComTpCd") === "1") {
            $c.util.getComponent('slc_ventDesignRsnCd').setDisabled(false);
        } else {
            $c.util.getComponent('slc_ventDesignRsnCd').setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05041.onloadDataSet" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/prelist.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/list/prelist.do",
        ref: "dma_loadListReq",
        target: "dlt_codeLeadcom=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openZipCodeWin
 * @description open Zip Code Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.openZipCodeWin = function () {
    if (scwin.zipCodeWin != null) {
        if (!scwin.zipCodeWin.closed) {
            scwin.zipCodeWin.close();
        }
    }
    scwin.zipCodeWin = (Promise.resolve($c.win.openPopup("/result_zipcode/result_zipcode.xml", { id: "pop_zip", width: "455px", height: "410px", scrollbars: false, resizable: false, type: "pageFramePopup" }, { zipCodeWin: (typeof scwin.zipCodeWin !== 'undefined' ? scwin.zipCodeWin : undefined) })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.returnZip).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.returnZip.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("pop_zip"); this.closed = true; } });
};

/**
 * @method
 * @name returnZip
 * @description return Zip 처리
 * @param {*} nodedata nodedata
 * @returns {void}
 * @hidden N
 */
scwin.returnZip = function (nodedata) {
    $c.util.getComponent('ipt_zipcd1').setValue(nodedata.zipcode1);
    $c.util.getComponent('ipt_zipcd2').setValue(nodedata.zipcode2);
    $c.util.getComponent('ipt_addr').setValue($c.util.getComponent('ipt_addr'));
};

/**
 * @method
 * @name openIndCodeWin
 * @description open Ind Code Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.openIndCodeWin = function () {
    if (scwin.indCodeWin != null) {
        if (!scwin.indCodeWin.closed) {
            scwin.indCodeWin.close();
        }
    }
    scwin.indCodeWin = (Promise.resolve($c.win.openPopup("/popup_indcode/popup_indcode.xml", { id: "pop_ind", width: "", height: "", scrollbars: false, resizable: false, type: "pageFramePopup" }, { indCodeWin: (typeof scwin.indCodeWin !== 'undefined' ? scwin.indCodeWin : undefined) })).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("pop_ind"); this.closed = true; } });
};

/**
 * @method
 * @name returnInd
 * @description return Ind 처리
 * @param {*} nodedata nodedata
 * @returns {void}
 * @hidden N
 */
scwin.returnInd = function (nodedata) {
    $c.util.getComponent('ipt_indCodeNm').setValue(nodedata.indname);
    $c.util.getComponent('ipt_indCdMrdtlclssCd').setValue(nodedata.indcode);
};

/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function () {
    if (!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) {
        return false;
    }
    if ($c.util.getComponent('ipt_isurCd').getValue().length !== 5) {
        await $c.win.alert("발행기관코드를 정확히 입력해주십시요.");
