/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (await scwin.vailidationLn() === false) {
        return;
    }
    if (!await scwin.setDataRadio()) {
        return;
    }
    scwin.setDataMergeDate();
    scwin.setDataCheckbox();
    scwin.form.action = '/list/prelist.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistReg');
    await scwin.tx_fn_Register();
};

