/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {*} corpRegNo corpRegNo
 * @param {*} bzRegNo bzRegNo
 * @param {String} repIsuCd repIsuCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {String} comEngNm comEngNm
 * @param {String} ceoNm ceoNm
 * @param {String} zipCd zipCd
 * @param {*} addr addr
 * @param {*} hPage hPage
 * @param {String} cntrIsoCd cntrIsoCd
 * @param {String} foundDd foundDd
 * @param {*} corpTelNo corpTelNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (isurCd, corpRegNo, bzRegNo, repIsuCd, repIsuSrtCd, comNm, comEngNm, ceoNm, zipCd, addr, hPage, cntrIsoCd, foundDd, corpTelNo) {
    $c.util.getComponent('dma_RegisterReq').reset();
    let isFCorp = false;
    const isurCd_first = isurCd.charAt(0);
    if (isNaN(isurCd_first)) {
        isFCorp = true;
    }
    if (('' !== isurCd) && (isurCd.length === 5)) {
        $c.util.getComponent("ipt_isurCd").setValue(isurCd);
    } else {
        await $c.win.alert('선택하신 법인의 고유코드가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
        return;
    }
    if (('' !== corpRegNo) && (corpRegNo.length === 13)) {
        $c.util.getComponent("ipt_corpRegNo1").setValue(corpRegNo.substring(0, 6));
        $c.util.getComponent("ipt_corpRegNo2").setValue(corpRegNo.substring(6));
    }
    if (('' !== bzRegNo) && (bzRegNo.length === 10)) {
        $c.util.getComponent("ipt_bzRegNo1").setValue(bzRegNo.substring(0, 3));
        $c.util.getComponent("ipt_bzRegNo2").setValue(bzRegNo.substring(3, 5));
        $c.util.getComponent("ipt_bzRegNo3").setValue(bzRegNo.substring(5));
    }
    if ('' !== comNm) {
        $c.util.getComponent("ipt_comNm").setValue(comNm);
    } else {
        await $c.win.alert('선택하신 법인의 회사명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    $c.util.getComponent("ipt_comEngNm").setValue(comEngNm);
    if ('' !== ceoNm) {
        $c.util.getComponent("ipt_repNm").setValue(ceoNm);
    } else {
        await $c.win.alert('선택하신 법인의 대표자명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    if (('' !== zipCd) && (zipCd.length === 6)) {
        $c.util.getComponent("ipt_zipcd1").setValue(zipCd.substring(0, 3));
        $c.util.getComponent("ipt_zipcd2").setValue(zipCd.substring(3));
    }
    $c.util.getComponent("ipt_addr").setValue(addr);
    $c.util.getComponent("slc_cntrIsoCd").setValue(cntrIsoCd);
    $c.util.getComponent("cal_foundDd").setValue(foundDd);
    $c.util.getComponent("ipt_telNo").setValue(corpTelNo);
    $c.util.getComponent('rd_prelmInvstgComTpCd1').setValue('5');
};

/**
 * @method
 * @name setRadioValue
 * @description set Radio Value 처리
 * @param {*} radioName radioName
 * @param {*} formParamName formParamName
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setRadioValue = async function (radioName, formParamName, msg) {
    const i = 0;
    const form = (document.irDataForm || { elements: [] });
    {
        const rv = String($c.util.getComponent('dma_RegisterReq').get(radioName) ?? '');
        if (rv === '') {
            await $c.win.alert(msg + " 항목을 선택해주세요.");
            return false;
        }
        $c.util.getComponent('dma_RegisterReq').set(formParamName, rv);
    }
    return true;
};

/**
 * @method
 * @name changePage
 * @description change Page 처리
 * @param {*} pageIndex pageIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changePage = async function (pageIndex) {
    //    if( eval(form.nowPage.value) <= eval(form.billLstSaveStatCd.value) || eval(pageIndex) <= (eval(form.billLstSaveStatCd.value) + 1)) {
    if( (pageIndex) <= (($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd")) + 1)) {

        $c.util.getComponent("dma_RegisterReq").set("nowPage", pageIndex);

        //        window.status=pageIndex + "page로 이동중" ;
        if( (pageIndex) < 5 ) {
            scwin.form.action = '/list/prelist.do';
            $c.util.getComponent('dma_RegisterReq').set('method', 'prelistSearch');
        } else {
            scwin.form.action = '/list/prelistEtc.do';
            $c.util.getComponent('dma_RegisterReq').set('method', 'prelistSearchEtc');
        }
        await moveUrl('/list/prelist.do', {});

    } else {
        await $c.win.alert("현재페이지의 항목들을 저장후에 다음 페이지로 이동할수 있습니다.");
        return ;
    }

};

